import { Component } from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { CreditoService } from '../../../../controllers/credito.service';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../../services/utils.service';
import { TablaComponent, TableDefinition } from "../../../../shared/tabla/tabla.component";
import { VerificacionCreditoService } from '../../../../controllers/verificacion.credito.service';

import { Button } from '../../../../shared/button/button.component';

const TABLA_DEF:TableDefinition={
  emptyMsg:'No hay verificaciones disponibles para este credito',
  columns:['concepto','revision_datos_ingresados','visita_domicilio','llamada_telefonica','']
}

@Component({
    selector: 'app-list-verificaciones-credito',
    imports: [
    TablaComponent
],
    templateUrl: './list-verificaciones-credito.component.html',
    styleUrl: './list-verificaciones-credito.component.css'
})
export class ListVerificacionesCreditoComponent {
  tabla = TABLA_DEF
  credito?:Credito

  constructor(
    private creditoController: CreditoService,
    private route:ActivatedRoute,
    private utils:UtilsService,
    public verificacionesCreditoController: VerificacionCreditoService
  ){}

  ngOnInit(){
    this.route.parent?.paramMap.subscribe(async (params)=>{
      const credito_id= this.utils.intOrNull(params.get('credito_id'))
      if(credito_id){
        this.credito= await this.creditoController.find(credito_id)
      }
    })
  }
}
